+SmallVector<int32_t> LocalMemOpTile::getLaneMask(ArrayRef<int32_t> lane) const {
+  SmallVector<int32_t> ret;
+  ret.reserve(laneMask.size());
+  for (int32_t mask : laneMask) {
+    int32_t basis = 0;
+    for (auto [idx, laneBasis] : llvm::enumerate(lane)) {
+      if (mask & (1 << idx)) {
+        basis ^= laneBasis;
+      }
+    }
+    ret.push_back(basis);
+  }
+  return ret;
+}
